base=json.loads(Path('scenarios/saturated-monoketones-nomenclature.scenario.json').read_text())
lesson={k:deepcopy(v) for k,v in base.items() if k!='steps'};lesson['title']=lesson['scenario']='Άλλες κετόνες';steps=[]
for i,(key,title,note,mode,hidden) in enumerate(rows,1):
 s=deepcopy(base['steps'][0]);s.update(n=i,title=title,note=note,selectedMol=key,nameAnalysisMode=mode,menuSubset=keys)
 s['title']=re.sub(r'(?<=[Α-ωάέήίόύώϊϋΐΰ])(?=\d)',' ',s['title'])
 s['note']=re.sub(r'(?<=[Α-ωάέήίόύώϊϋΐΰ])(?=\d)',' ',s['note'])
 s['styleName']['hidden']=hidden
 if i in [7,27,28]:
  s['show'].update(controls={'2D':True,'3D':i==28},nameSettings=True,nameClick=True,menu=i>=27)
 if i==28:s['show'].update(viewers={'2D':True,'3D':True},viewerBothHeight=840)
 steps.append(s)
lesson['steps']=steps
p=Path('scenarios/other-ketones-nomenclature.scenario.json');assert not p.exists();p.write_text(json.dumps(lesson,ensure_ascii=False,indent=2)+'\n')
print('Authored',len(steps),'steps',len(keys),'molecules')
